	[ 'eans' => [ '1240000025552' ], 'html' => '<p>Kompakt blender i sort, 850 W, fra Beast – model Mighty Plus 850. Den fylder lidt, men kører stærkt nok til smoothies, dips, dressinger, desserter og cocktails på få sekunder. Få knapper og en robust opbygning gør den enkel at bruge hver dag.</p><ul><li>850 W</li><li>Farve: sort</li></ul>' ],
