	[ 'eans' => [ '6414676023470' ], 'html' => '<p>Muurikkas stegeplade kommer nemt med i skoven, når den ligger i denne rygsæk, der er syet efter pladens form. Den passer til pladen med en diameter på 48 cm.</p><ul><li>Til stegeplade Ø48 cm</li><li>Formtilpasset</li></ul>' ],
