	[ 'eans' => [ '3546698942569' ], 'html' => '<p>Laguiole er navnet på en fransk landsby, hvor denne bestiktype har sin oprindelse, og kniven i dette sæt fra Lou Laguiole kombinerer de traditionelle knivformer Navaja og Capouchadou. Sættet her er i farven pearl.</p><ul><li>24 dele</li><li>Serie: Tradition</li><li>Farve: pearl</li></ul>' ],
