	[ 'eans' => [ '6414676023463' ], 'html' => '<p>Formsyet rygsæk fra Muurikka til den mindre stegeplade, så den kan bæres sikkert med på udflugt i skoven. Beregnet til pladen med en diameter på 38 cm.</p><ul><li>Til stegeplade Ø38 cm</li><li>Formtilpasset</li></ul>' ],
