	[ 'eans' => [ '6414676027058' ], 'html' => '<p>Boksen hænges på kanten af Muurikkas store stegeplade, så madrester og fedt kan skrabes direkte ned i den efter brug. Det gør oprydningen hurtigere.</p><ul><li>Til stegeplade 100/120</li><li>Hænges på kanten</li></ul>' ],
