	[ 'eans' => [ '7350011670673' ], 'html' => '<p>Riller i bunden giver kød og grøntsager flotte grillstriber og løfter dem lidt op fra bunden – uden at du skal tænde grillen. Carl Victors Gold-pande er i støbejern, der tåler høj varme.</p><ul><li>Diameter: 28 cm</li><li>Støbejern</li><li>Rillet stegeflade</li></ul>' ],
