	[ 'eans' => [ '5020403172826' ], 'html' => '<p>Genwares cocktailkop i rustfrit stål er formet som en ananas og, som rummer 44 cl. Formen hører til i tiki-drinks og andre tropiske cocktails, hvor serveringen er en del af oplevelsen, og stålet holder på kulden, når drinken er fyldt med is.</p><ul><li>Rummer 44 cl</li><li>Rustfrit stål</li><li>Ananasform</li></ul>' ],
