	[ 'eans' => [ '4011833200327' ], 'html' => '<p>Stor airfryer fra Steba, HF5000 XL, med non-stick stegekurv på 5,2 liter. Den har syv automatiske programmer til pommes frites, kylling og fisk.</p>' ],
