	[ 'eans' => [ '6975723610116' ], 'html' => '<p>Fire prober og en smart basestation giver temperaturovervågning af flere stykker mad på én gang. Forbindelsen kører via Bluetooth 5.3 og WiFi, så du kan holde øje med tilberedningen trådløst.</p><ul><li>Fire præcisionsprober</li><li>Bluetooth 5.3</li><li>WiFi</li></ul>' ],
