	[ 'eans' => [ '6424002019923' ], 'html' => '<p>Pandekagepande på 22 cm med keramisk Ceratec Superior-belægning, som skal få pandekager og omeletter til at glide let af. Størrelsen passer til hverdagens små og mellemstore portioner.</p>' ],
